/**
 * @param {number} low
 * @param {number} high
 * @return {number[]}
 */
var sequentialDigits = function(low, high) {
    const res = new Set();

    const dfs = (num) => {
        if (num > high) return;

        if (num >= low) {
            res.add(num);
        }

        const lastDigit = num % 10;

        if (lastDigit === 9) return;

        num = num * 10 + (lastDigit + 1);

        dfs(num);
    };

    for (let i = 1; i <= 9; i++) {
        dfs(i);
    }

    return [...res].sort((a, b) => a - b);
};
